{
  "propositions": [
    {
      "text": "\"无穷\"曾经是数学的禁区。",
      "exactQuote": "\"无穷\"曾经是数学的禁区。",
      "blockId": "03-sequences-limits#block-1"
    },
    {
      "text": "极限概念的严格化（19世纪的 ε-δ 革命）是数学史上从直觉到精确的最大飞跃。",
      "exactQuote": "极限概念的严格化（19世纪的 $\\epsilon$-\\delta$ 革命）是数学史上从直觉到精确的最大飞跃。",
      "blockId": "03-sequences-limits#block-1"
    },
    {
      "text": "本章既是微积分的基石，也是分析学的方法论核心。",
      "exactQuote": "本章既是微积分的基石，也是分析学的方法论核心。",
      "blockId": "03-sequences-limits#block-1"
    },
    {
      "text": "数列是定义在自然数上的函数：a: ℕ → ℝ（或 ℂ），记作 (a_n)_{n=1}^∞。",
      "exactQuote": "**数列** = 定义在自然数上的函数：$a: \\mathbb{N} \\to \\mathbb{R}$（或 $\\mathbb{C}$），记作 $(a_n)_{n=1}^\\infty$。",
      "blockId": "03-sequences-limits#block-5"
    },
    {
      "text": "数列是离散动力系统的最简形式——它描述了一个量在离散时间步骤上的演化。",
      "exactQuote": "数列是**离散动力系统**的最简形式——它描述了一个量在离散时间步骤上的演化。",
      "blockId": "03-sequences-limits#block-7"
    },
    {
      "text": "等差数列定义为 a_{n+1} = a_n + d。",
      "exactQuote": "等差数列 | $a_{n+1} = a_n + d$ | $1, 3, 5, 7, \\ldots$",
      "blockId": "03-sequences-limits#block-8"
    },
    {
      "text": "等比数列定义为 a_{n+1} = a_n · q。",
      "exactQuote": "等比数列 | $a_{n+1} = a_n \\cdot q$ | $1, 2, 4, 8, \\ldots$",
      "blockId": "03-sequences-limits#block-8"
    },
    {
      "text": "递推数列定义为 a_{n+1} = f(a_n) 或 a_{n+2} = f(a_n, a_{n+1})。",
      "exactQuote": "递推数列 | $a_{n+1} = f(a_n)$ 或 $a_{n+2} = f(a_n, a_{n+1})$ | Fibonacci: $a_{n+2}=a_{n+1}+a_n$",
      "blockId": "03-sequences-limits#block-8"
    },
    {
      "text": "Cauchy列定义为：∀ε>0, ∃N, ∀m,n>N: |a_m - a_n| < ε。",
      "exactQuote": "Cauchy列 | $\\forall \\epsilon>0, \\exists N, \\forall m,n>N: \\lvert a_m-a_n\\rvert<\\epsilon$ | $a_n = 1/n$",
      "blockId": "03-sequences-limits#block-8"
    },
    {
      "text": "18世纪的数学家说\"a_n 无限接近 L\"就够了。",
      "exactQuote": "18世纪的数学家说\"$a_n$ 无限接近 $L$\"就够了。",
      "blockId": "03-sequences-limits#block-12"
    },
    {
      "text": "\"无限接近\"导致了大量混乱和错误。",
      "exactQuote": "但\"无限接近\"是什么意思？这导致了大量混乱和错误。",
      "blockId": "03-sequences-limits#block-12"
    },
    {
      "text": "19世纪，Cauchy、Weierstrass 等人用逻辑量词给出了极限的精确刻画。",
      "exactQuote": "19世纪，Cauchy、Weierstrass 等人用逻辑量词给出了精确的刻画。",
      "blockId": "03-sequences-limits#block-12"
    },
    {
      "text": "数列极限定义为：lim_{n→∞} a_n = L 当且仅当 ∀ε > 0, ∃N ∈ ℕ, ∀n > N: |a_n - L| < ε。",
      "exactQuote": "$\\lim_{n \\to \\infty} a_n = L$ 当且仅当：\n\n$$\\forall \\epsilon > 0, \\; \\exists N \\in \\mathbb{N}, \\; \\forall n > N: |a_n - L| < \\epsilon$$",
      "blockId": "03-sequences-limits#block-13"
    },
    {
      "text": "ε-N 论证像一个挑战游戏：对手出 ε，我方出 N，如果总能赢，极限成立。",
      "exactQuote": "$\\epsilon$-$N$ 论证像一个\"挑战游戏\"。对手出 $\\epsilon$（想要多小就多小），我们出 $N$——如果能永远赢下去，极限就成立了。",
      "blockId": "03-sequences-limits#block-16"
    },
    {
      "text": "1/n 的极限是 0。",
      "exactQuote": "$\\frac{1}{n}$ | $0$ | $N = \\lceil 1/\\epsilon \\rceil$",
      "blockId": "03-sequences-limits#block-20"
    },
    {
      "text": "1/n^p (p>0) 的极限是 0。",
      "exactQuote": "$\\frac{1}{n^p}$ ($p>0$) | $0$ | 任意多项式倒数→0",
      "blockId": "03-sequences-limits#block-20"
    },
    {
      "text": "q^n (|q|<1) 的极限是 0。",
      "exactQuote": "$q^n$ ($\\lvert q\\rvert<1$) | $0$ | 几何衰减",
      "blockId": "03-sequences-limits#block-20"
    },
    {
      "text": "n 次根号下 n (√[n]{n}) 的极限是 1。",
      "exactQuote": "$\\sqrt[n]{n}$ | $1$ | 慢收敛",
      "blockId": "03-sequences-limits#block-20"
    },
    {
      "text": "(1 + 1/n)^n 的极限是 e。",
      "exactQuote": "$(1 + \\frac{1}{n})^n$ | $e$ | $\\S$11 常数",
      "blockId": "03-sequences-limits#block-20"
    },
    {
      "text": "sin n / n 的极限是 0（由夹逼定理）。",
      "exactQuote": "$\\frac{\\sin n}{n}$ | $0$ | 夹逼定理",
      "blockId": "03-sequences-limits#block-20"
    }
  ]
}
